// Generated by AI (UnitTest MCP)
//
// The ADR record must come from main, not from whichever worktree asked.
//
// Under ADR-0038 concurrent work lives in many worktrees on different branches,
// so `readdirSync(docs/adr)` answers a different question in each one. Measured
// across 84 attached worktrees on 2026-07-30: 75 ADRs on origin/main, the union
// across all 196 remote branches also 75 -- so main is the complete record and
// nothing is ever branch-only -- yet 65 worktrees were missing between 1 and 26
// of them, and the checkout the extension itself reads saw 49 of 75 with no
// error of any kind. A third of the design record simply absent.
import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { readAdrFilesFromMain } from "../../../scripts/adr-files.mjs";

const directories = [];
const scratch = (prefix) => {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  directories.push(dir);
  return dir;
};
afterEach(() => {
  for (const dir of directories.splice(0)) rmSync(dir, { recursive: true, force: true });
});

const git = (repo, args) =>
  execFileSync("git", args, { cwd: repo, encoding: "utf8", stdio: "pipe" });

/**
 * A repository whose `main` holds `onMain`, checked out on a branch that holds
 * `onBranch` instead -- the shape every worktree in the fleet is actually in.
 */
const repositoryWhereMainAndTheCheckoutDiffer = (onMain, onBranch) => {
  const origin = scratch("adr-origin-");
  git(origin, ["init", "--quiet", "--initial-branch=main"]);
  git(origin, ["config", "user.email", "test@example.com"]);
  git(origin, ["config", "user.name", "Test"]);
  mkdirSync(join(origin, "docs", "adr"), { recursive: true });
  for (const [name, body] of Object.entries(onMain)) {
    writeFileSync(join(origin, "docs", "adr", name), body);
  }
  git(origin, ["add", "-A"]);
  git(origin, ["commit", "--quiet", "-m", "adrs on main"]);

  const clone = scratch("adr-clone-");
  git(clone, ["clone", "--quiet", origin, "."]);
  git(clone, ["config", "user.email", "test@example.com"]);
  git(clone, ["config", "user.name", "Test"]);
  git(clone, ["checkout", "--quiet", "-b", "feature"]);
  // Roll the checkout back to a state that predates the ADRs on main, which is
  // what a worktree branched days ago looks like.
  rmSync(join(clone, "docs", "adr"), { recursive: true, force: true });
  mkdirSync(join(clone, "docs", "adr"), { recursive: true });
  for (const [name, body] of Object.entries(onBranch)) {
    writeFileSync(join(clone, "docs", "adr", name), body);
  }
  git(clone, ["add", "-A"]);
  git(clone, ["commit", "--quiet", "-m", "branch has fewer"]);
  return clone;
};

const adr = (n, title, status) => `# ADR-${n}: ${title}\n\n- Status: ${status}\n`;

// Every case here spawns real git repositories and clones them. Set on the
// suite rather than per test, for the reason adr-guard.test.mjs already
// records: the slow part is git, which every case uses, so a per-test timeout
// is one the next test added will forget. Passing alone at ~3s each and failing
// only under full-suite load is what that looks like.
const GIT_TEST_TIMEOUT_MS = 60_000;

describe(
  "readAdrFilesFromMain",
  () => {
    it("reads the ADRs on main, not the ones the checkout happens to have", () => {
      const repo = repositoryWhereMainAndTheCheckoutDiffer(
        {
          "0001-first.md": adr("0001", "First", "Accepted"),
          "0002-second.md": adr("0002", "Second", "Proposed"),
          "0003-third.md": adr("0003", "Third", "Accepted"),
        },
        { "0001-first.md": adr("0001", "First", "Accepted") }
      );

      const { files, source, fellBack } = readAdrFilesFromMain({ cwd: repo });

      expect(files.map((f) => f.number)).toEqual(["0001", "0002", "0003"]);
      expect(fellBack).toBe(false);
      expect(source).toContain("main");
    });

    it("still parses title and status the same way as the on-disk reader", () => {
      const repo = repositoryWhereMainAndTheCheckoutDiffer(
        { "0039-every-waiver-ends.md": adr("0039", "Every waiver ends", "Accepted") },
        {}
      );

      const { files } = readAdrFilesFromMain({ cwd: repo });

      expect(files[0]).toMatchObject({
        number: "0039",
        title: "Every waiver ends",
        status: "Accepted",
        path: "docs/adr/0039-every-waiver-ends.md",
      });
    });

    /// Falling back is correct in a fresh clone with no remote. Falling back
    /// *silently* is the failure being fixed -- a partial record that reports
    /// itself as complete is worse than an error, because every tool downstream
    /// then reports confident nonsense about design drift.
    it("falls back to the working tree when main cannot be resolved, and says so", () => {
      const repo = scratch("adr-noremote-");
      git(repo, ["init", "--quiet", "--initial-branch=main"]);
      mkdirSync(join(repo, "docs", "adr"), { recursive: true });
      writeFileSync(join(repo, "docs", "adr", "0007-local.md"), adr("0007", "Local", "Proposed"));

      const warnings = [];
      const { files, fellBack, source } = readAdrFilesFromMain({
        cwd: repo,
        warn: (message) => warnings.push(message),
      });

      expect(files.map((f) => f.number)).toEqual(["0007"]);
      expect(fellBack).toBe(true);
      expect(source).toContain("working tree");
      expect(warnings.join("\n")).toMatch(/working tree/i);
    });
  },
  GIT_TEST_TIMEOUT_MS
);
